#!/bin/bash
#
# run_boltz_evaluation.sh
#
# SLURM script to re-evaluate ODesign candidates with Boltz-2.
# Runs Boltz-2 on all YAML files in a specified directory, producing
# full-atom structures and affinity predictions for each.
#
# Usage:
#   sbatch run_boltz_evaluation.sh <input_dir>
#
# Example:
#   sbatch run_boltz_evaluation.sh $SCRATCH/boltz/inputs/odesign_eval
#
# Prerequisites:
#   - boltz2 conda environment set up via setup_boltz.sh
#   - YAML files generated by prepare_boltz_inputs.py

#SBATCH -A gpu
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=8
#SBATCH --mem=96G
#SBATCH --gpus-per-node=1
#SBATCH --constraint=J
#SBATCH --time=01:00:00
#SBATCH --job-name boltz_eval
#SBATCH --output=%x-%J-%u.out
#SBATCH --error=%x-%J-%u.err
#SBATCH --mail-type=BEGIN,END,FAIL
#SBATCH --mail-user=${USER}@purdue.edu

set -euo pipefail

# -----------------------------------------------------------------------
# Environment setup
# -----------------------------------------------------------------------
ml conda
source activate "$SCRATCH/conda/envs/boltz2"

export PIP_CACHE_DIR="$SCRATCH/conda/pip-cache"
export XDG_CACHE_HOME="$SCRATCH/conda/xdg-cache"
export BOLTZ_CACHE="$SCRATCH/conda/boltz-cache"

# -----------------------------------------------------------------------
# Determine input directory
# -----------------------------------------------------------------------
if [[ -z "${1:-}" ]]; then
    echo "Error: must provide input directory containing YAML files."
    echo "Usage: sbatch run_boltz_evaluation.sh <input_dir>"
    exit 1
fi

INPUT_DIR="$1"
if [[ ! -d "$INPUT_DIR" ]]; then
    echo "Error: input directory '$INPUT_DIR' not found."
    exit 1
fi

OUTPUT_DIR="$SCRATCH/boltz/outputs/odesign_eval"
mkdir -p "$OUTPUT_DIR"

# -----------------------------------------------------------------------
# Report environment
# -----------------------------------------------------------------------
echo "=== Boltz-2 ODesign Evaluation ==="
echo "Date:       $(date)"
echo "Node:       $(hostname)"
echo "GPU:        $(nvidia-smi --query-gpu=name,memory.total --format=csv,noheader 2>/dev/null || echo 'N/A')"
echo "Input dir:  $INPUT_DIR"
echo "Output dir: $OUTPUT_DIR"
echo ""
echo "YAML files to process:"
ls -1 "$INPUT_DIR"/*.yaml 2>/dev/null || { echo "ERROR: no YAML files"; exit 1; }
echo ""

# -----------------------------------------------------------------------
# Run Boltz-2 on the entire input directory
# -----------------------------------------------------------------------
# Boltz accepts a directory and will process every YAML in it.
# --use_msa_server will generate MSAs for MDM2 automatically (small
# peptide binders don't need MSAs, only the target does).

boltz predict "$INPUT_DIR" \
    --out_dir "$OUTPUT_DIR" \
    --use_msa_server \
    --diffusion_samples 5 \
    --num_workers 0

echo ""
echo "=== Boltz-2 evaluation complete ==="
echo "Results in: $OUTPUT_DIR"
find "$OUTPUT_DIR" -name "*.cif" -o -name "affinity_*.json" | head -30
